"""Regenerate pinned sigma-property ranges from rust-src unicode_data.rs."""
import bisect
import hashlib
import pathlib
import re
import sys

source = pathlib.Path(sys.argv[1]).read_text()
output = ["// Copyright the Rust Project Developers. MIT OR Apache-2.0.",
          "// Generated by generate.py from the pinned unicode_data.rs.",
          "// SHA256 " + hashlib.sha256(source.encode()).hexdigest(), ""]
for module, expected_ranges, expected_count in [("case_ignorable", 459, 2789), ("lt", 10, 31)]:
    body = source.split("pub mod " + module + " {", 1)[1].split("\n}\n", 1)[0]
    headers = [(int(a), int(b)) for a, b in re.findall(r"ShortOffsetRunHeader::new\((\d+), (\d+)\)", body)]
    offsets = list(map(int, re.findall(r"\d+", body.split("static OFFSETS:", 1)[1].split("= [", 1)[1].split("];", 1)[0])))
    prefixes = [b for _, b in headers]
    def lookup(code):
        last = bisect.bisect_right(prefixes, code)
        index = headers[last][0]
        length = (headers[last + 1][0] if last + 1 < len(headers) else len(offsets)) - index
        total = code - (prefixes[last - 1] if last else 0)
        prefix = 0
        for _ in range(length - 1):
            prefix += offsets[index]
            if prefix > total:
                break
            index += 1
        return index % 2 == 1
    ranges = []
    start = None
    count = 0
    for code in range(0x110001):
        member = code < 0x110000 and lookup(code)
        if member:
            count += 1
            if start is None:
                start = code
        elif start is not None:
            ranges.append((start, code))
            start = None
    assert len(ranges) == expected_ranges, (module, len(ranges))
    assert count == expected_count, (module, count)
    output.append("pub(super) const " + module.upper() + ": &[(u32, u32)] = &[")
    for index in range(0, len(ranges), 4):
        output.append("    " + " ".join(f"(0x{a:X}, 0x{b:X})," for a, b in ranges[index:index + 4]))
    output.extend(["];", ""])
pathlib.Path(__file__).with_name("properties.rs").write_text("\n".join(output))
